// Costruisce il sito EUROWORK (cartella "dist") a partire da contenuti/sito.json.
// Stile: "Cantiere" — cinematografico, scuro, elegante.
// Netlify/GitHub lo eseguono da soli a ogni modifica salvata dal pannello Pages CMS.
// Per provarlo sul computer: node build.js  (poi apri dist/index.html)

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const OUT = path.join(ROOT, 'dist');
const LOGO = 'data:image/png;base64,';

const d = JSON.parse(fs.readFileSync(path.join(ROOT, 'contenuti', 'sito.json'), 'utf8'));

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const br = (v) => esc(v).replace(/\r?\n/g, '<br>');
const lista = (v) => (Array.isArray(v) ? v : []);
const img = (p) => esc(String(p || '').replace(/^\/+/, ''));
const tel = (n) => { let x = String(n || '').replace(/[^\d+]/g, ''); if (x && !x.startsWith('+')) x = '+39' + x; return x; };
const inquadra = { alto: 'center 22%', centro: 'center', basso: 'center 78%' };
const num = (t) => { const m = String(t ?? '').match(/^\s*([\d.,]+)(.*)$/); return m ? `${m[1]}<em>${esc(m[2].trim())}</em>` : esc(t); };

const a = d.apertura || {}, sv = d.servizi || {}, cs = d.chi_siamo || {}, es = d.esperienza || {};
const lv = d.lavori || {}, g = d.galleria || {}, q = d.qualificazioni || {}, c = d.contatti || {}, ds = d.dati_societari || {};
const fotoG = lista(g.foto).filter((f) => f && f.immagine);
const heroImgs = [...new Set([a.foto, ...lista(lv.elenco).map((l)=>l.foto), ...fotoG.map((f)=>f.immagine)].filter(Boolean))].slice(0,5);

const html = `<!doctype html>
<html lang="it">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(d.seo?.titolo)}</title>
<meta name="description" content="${esc(d.seo?.descrizione)}">
<link rel="icon" type="image/png" href="img/favicon.png">
<meta name="theme-color" content="#0e0e0f">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,500;1,9..144,400&family=Archivo:wght@400;500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="stile.css">
</head>
<body>

<header id="header">
  <div class="wrap nav">
    <a href="#top" class="logo" aria-label="EUROWORK"><img src="${LOGO}" alt="EUROWORK"></a>
    <button class="menuico" aria-expanded="false" aria-controls="menu" onclick="const u=document.getElementById('menu');this.setAttribute('aria-expanded',u.classList.toggle('aperto'))"><span></span><span></span></button>
    <nav><ul id="menu" onclick="this.classList.remove('aperto')">
      <li><a href="#servizi">Servizi</a></li>
      <li><a href="#storia">Azienda</a></li>
      <li><a href="#lavori">Lavori</a></li>
      ${fotoG.length ? '<li><a href="#galleria">Galleria</a></li>' : ''}
      <li><a href="#contatti" class="linkcta">Contatti</a></li>
    </ul></nav>
  </div>
</header>

<main id="top">

<section class="hero">
  <div class="hero-slide" role="img" aria-label="${esc(a.descrizione_foto)}">
    ${heroImgs.map((f,i)=>`<div class="hero-bg${i?'':' on'}" style="background-image:url('${img(f)}')"></div>`).join('')}
  </div>
  <div class="wrap hero-in">
    <div class="kicker">${esc(a.etichetta)}</div>
    <h1>${esc(a.titolo)}</h1>
    <div class="hero-foot">
      <p>${br(a.testo)}</p>
      <a href="#servizi" class="scopri">Scopri cosa facciamo <span>↓</span></a>
    </div>
  </div>
</section>

<section class="numeri-sez">
  <div class="wrap numeri">
    ${lista(d.numeri).map((n) => `<div class="numero"><b>${num(n.valore)}</b><span>${esc(n.descrizione)}</span></div>`).join('')}
  </div>
</section>

<section id="servizi" class="sez chiaro">
  <div class="wrap">
    <div class="testa">
      <span class="lbl">Servizi</span>
      <h2>${esc(sv.titolo)}</h2>
      <p class="guida">${br(sv.testo)}</p>
    </div>
    <div class="serv-lista">
      ${lista(sv.elenco).map((s) => `<article class="serv${s.in_evidenza ? ' spicca' : ''}">
        <h3>${esc(s.titolo)}</h3>
        <p>${br(s.testo)}</p>
      </article>`).join('')}
    </div>
    ${lista(sv.altri).length ? `<div class="altri">
      ${lista(sv.altri).map((gr) => `<details><summary>${esc(gr.titolo)}<span class="pi"></span></summary><ul>${lista(gr.voci).map((v) => `<li>${esc(v)}</li>`).join('')}</ul></details>`).join('')}
    </div>` : ''}
  </div>
</section>

<section id="storia" class="sez storia-sez">
  <div class="wrap storia">
    <div>
      <span class="lbl">Chi siamo</span>
      <h2>${esc(cs.titolo)}</h2>
      ${lista(cs.paragrafi).map((p) => `<p class="corpo">${br(p)}</p>`).join('')}
      <div class="persone">
        ${lista(cs.persone).map((p) => `<div class="persona"><b>${esc(p.nome)}</b><span>${esc(p.ruolo)}</span></div>`).join('')}
      </div>
    </div>
    <ol class="timeline">
      ${lista(cs.tappe).map((t) => `<li${t.in_evidenza ? ' class="ora"' : ''}><span class="anno">${esc(t.anno)}</span><h3>${esc(t.titolo)}</h3><p>${br(t.testo)}</p></li>`).join('')}
    </ol>
  </div>
</section>

<section id="esperienza" class="sez chiaro">
  <div class="wrap esp">
    <div class="esp-testo">
      <span class="lbl">Esperienza</span>
      <h2>${esc(es.titolo)}</h2>
      <p class="corpo">${br(es.testo)}</p>
      ${lista(es.clienti).length ? `<div class="clienti"><span class="mini">${esc(es.clienti_titolo)}</span><div class="loghi">${lista(es.clienti).map((x) => `<span>${esc(x)}</span>`).join('')}</div></div>` : ''}
      ${es.premio_titolo ? `<div class="premio"><b>${esc(es.premio_titolo)}</b><span>${esc(es.premio_testo)}</span></div>` : ''}
    </div>
    <div class="tratte" id="tratte">
      <span class="mini">Tratte dirette</span>
      ${lista(es.tratte).map((t) => { const b = Math.max(0, Math.min(100, Number(t.barra) || 0));
        return `<div class="tratta"><div class="riga"><b>${esc(t.nome)}</b><strong>${esc(t.valore)}</strong></div>${b ? `<div class="barra"><i style="--l:${b}%"></i></div>` : '<div class="barra vuota"></div>'}</div>`; }).join('')}
    </div>
  </div>
</section>

<section id="lavori" class="sez lavori-sez">
  <div class="wrap">
    <div class="testa"><span class="lbl">Cantieri</span><h2>${esc(lv.titolo)}</h2></div>
  </div>
  <div class="wrap lavori">
    ${lista(lv.elenco).map((l, i) => `<article class="lavoro">
      <div class="foto" style="background-image:url('${img(l.foto)}');background-position:${inquadra[l.inquadratura] || 'center'}"></div>
      <div class="didas"><span class="idx">0${i + 1}</span><h3>${esc(l.titolo)}</h3></div>
    </article>`).join('')}
  </div>
</section>

${fotoG.length ? `<section id="galleria" class="sez galleria-sez">
  <div class="wrap">
    <div class="testa"><span class="lbl">Galleria</span><h2>${esc(g.titolo)}</h2>${g.testo ? `<p class="guida">${br(g.testo)}</p>` : ''}</div>
  </div>
  <div class="galleria" data-auto="${g.scorrimento_automatico ? '1' : '0'}" aria-label="Galleria foto">
    <div class="slides" tabindex="0">
      ${fotoG.map((f, i) => `<figure class="slide"><div class="sfondo" style="background-image:url('${img(f.immagine)}')"></div><img src="${img(f.immagine)}" alt="${esc(f.didascalia || 'Cantiere EUROWORK')}" loading="${i ? 'lazy' : 'eager'}">${f.didascalia ? `<figcaption>${esc(f.didascalia)}</figcaption>` : ''}</figure>`).join('')}
    </div>
    ${fotoG.length > 1 ? `<button class="freccia prec" aria-label="Precedente">‹</button><button class="freccia succ" aria-label="Successiva">›</button>
    <div class="puntini">${fotoG.map((_, i) => `<button aria-label="Foto ${i + 1}"${i ? '' : ' aria-current="true"'}></button>`).join('')}</div>` : ''}
  </div>
</section>` : ''}

<section class="sez chiaro qual-sez">
  <div class="wrap">
    <div class="testa"><span class="lbl">Qualificazioni</span><h2>${esc(q.titolo)}</h2></div>
    <div class="qual">
      ${lista(q.elenco).map((x) => `<div class="q"><b>${esc(x.titolo)}</b><span>${esc(x.testo)}</span></div>`).join('')}
    </div>
  </div>
</section>

<section id="contatti" class="sez contatti-sez">
  <div class="wrap">
    <div class="cta-fine">
      <span class="lbl">Lavoriamo insieme</span>
      <h2>${esc(c.titolo_riquadro)}</h2>
      <p class="guida">${br(c.testo_riquadro)}</p>
      <div class="azioni">
        ${c.email ? `<a class="btn" href="mailto:${esc(c.email)}?subject=Richiesta%20informazioni">Scrivici</a>` : ''}
        ${c.telefono ? `<a class="btn ghost" href="tel:${tel(c.telefono)}">Chiamaci</a>` : ''}
      </div>
    </div>
    <div class="contatti">
      <div class="contatto"><span class="mini">Sede legale</span><p>${esc(c.indirizzo)}<br>${esc(c.cap_citta)}</p></div>
      <div class="contatto"><span class="mini">Telefono e fax</span><p>${c.telefono ? `<a href="tel:${tel(c.telefono)}">${esc(c.telefono)}</a>` : ''}${c.cellulare ? `<br><a href="tel:${tel(c.cellulare)}">${esc(c.cellulare)}</a> (cell.)` : ''}</p></div>
      <div class="contatto"><span class="mini">${c.pec ? 'Email e PEC' : 'Email'}</span><p>${c.email ? `<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>` : ''}${c.pec ? `<br>${esc(c.pec)}` : ''}</p></div>
      ${c.orari ? `<div class="contatto"><span class="mini">Orari</span><p>${br(c.orari)}</p></div>` : ''}
    </div>
  </div>
</section>
</main>

<footer>
  <div class="wrap">
    <span>© <span id="anno"></span> ${esc(ds.ragione_sociale)} · P.IVA e C.F. ${esc(ds.piva_cf)} · REA ${esc(ds.rea)} · ${esc(ds.camera_commercio)}</span>
  </div>
</footer>

<script>
  document.getElementById('anno').textContent=new Date().getFullYear();
  const h=document.getElementById('header');
  addEventListener('scroll',()=>h.classList.toggle('su',scrollY>60),{passive:true});
  const t=document.getElementById('tratte');
  if(t){ if('IntersectionObserver' in window){ new IntersectionObserver((e,o)=>{if(e[0].isIntersecting){t.classList.add('vis');o.disconnect()}},{threshold:.25}).observe(t);} else t.classList.add('vis'); }
  var RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
  // slideshow in apertura
  var hs=document.querySelectorAll('.hero-bg');
  if(hs.length>1 && !RM){ var hi=0; setInterval(function(){ hs[hi].classList.remove('on'); hi=(hi+1)%hs.length; hs[hi].classList.add('on'); },4800); }
  // comparse morbide allo scroll
  if(!RM && 'IntersectionObserver' in window){
    document.documentElement.classList.add('anim');
    var els=document.querySelectorAll('.testa,.numero,.serv,.lavoro,.q,.tratta,.persona,.timeline li,.cta-fine,.premio,.clienti,.altri');
    els.forEach(function(e){e.classList.add('reveal')});
    var io=new IntersectionObserver(function(ents){ents.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}})},{threshold:.12,rootMargin:'0px 0px -8% 0px'});
    els.forEach(function(e){io.observe(e)});
  }
  document.querySelectorAll('.galleria').forEach(gal=>{
    const box=gal.querySelector('.slides'), slides=[...box.children], dots=[...gal.querySelectorAll('.puntini button')];
    if(slides.length<2) return;
    let i=0, timer=null;
    const vai=n=>{ i=(n+slides.length)%slides.length; box.scrollTo({left:slides[i].offsetLeft,behavior:'smooth'}); };
    gal.querySelector('.prec').onclick=()=>{vai(i-1);ferma()};
    gal.querySelector('.succ').onclick=()=>{vai(i+1);ferma()};
    dots.forEach((dt,n)=>dt.onclick=()=>{vai(n);ferma()});
    box.addEventListener('scroll',()=>{const n=Math.round(box.scrollLeft/box.clientWidth);if(n!==i)i=n;dots.forEach((dt,k)=>dt.setAttribute('aria-current',k===n?'true':'false'));},{passive:true});
    const rid=matchMedia('(prefers-reduced-motion: reduce)').matches;
    function parti(){ if(gal.dataset.auto==='1'&&!rid&&!timer) timer=setInterval(()=>vai(i+1),5200); }
    function ferma(){ clearInterval(timer); timer=null; }
    gal.addEventListener('mouseenter',ferma); gal.addEventListener('mouseleave',parti);
    gal.addEventListener('touchstart',ferma,{passive:true}); parti();
  });
</script>
</body>
</html>
`;

fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(path.join(OUT, 'index.html'), html);
fs.copyFileSync(path.join(ROOT, 'stile.css'), path.join(OUT, 'stile.css'));
fs.cpSync(path.join(ROOT, 'img'), path.join(OUT, 'img'), { recursive: true });
console.log('Sito (Cantiere) costruito in dist/');
